package cn.workbench;
import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;import javax.crypto.*;import javax.crypto.spec.*;import java.security.*;import java.util.*;
@Component public class Crypto {private final byte[] key; public Crypto(@Value("${task.totp-key:}")String k){key=k.isBlank()?null:Base64.getDecoder().decode(k);if(key!=null&&key.length!=32)throw new IllegalStateException("TASK_TOTP_ENCRYPTION_KEY must be base64 32 bytes");} public String encrypt(String text){if(key==null)throw new ApiException(503,"KEY_UNAVAILABLE","双因素密钥未配置");try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));return Base64.getEncoder().encodeToString(iv)+":"+Base64.getEncoder().encodeToString(c.doFinal(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}} public String decrypt(String encrypted){if(key==null)throw new ApiException(503,"KEY_UNAVAILABLE","双因素密钥未配置");try{String[] a=encrypted.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,Base64.getDecoder().decode(a[0])));return new String(c.doFinal(Base64.getDecoder().decode(a[1])),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("TOTP decryption failed");}}}
